#include <iostream>
#include <memory>

template <typename T>
struct TreeNode {
    T data;
    std::unique_ptr<TreeNode<T>> leftPtr;
    std::unique_ptr<TreeNode<T>> rightPtr;

    explicit TreeNode(const T& val) : data(val), leftPtr(nullptr), rightPtr(nullptr) {}
};

template <typename T>
class BST {
public:
    BST() = default;

    void insert(const T& val) {
        insertHelper(root, val);
    }

    void inOrder() const {
        inOrderHelper(root.get());
        std::cout << '\n';
    }

    void preOrder() const {
        preOrderHelper(root.get());
        std::cout << '\n';
    }

    void postOrder() const {
        postOrderHelper(root.get());
        std::cout << '\n';
    }

private:
    std::unique_ptr<TreeNode<T>> root;

    void insertHelper(std::unique_ptr<TreeNode<T>>& ptr, const T& val) {
        if (!ptr) {
            ptr = std::make_unique<TreeNode<T>>(val);
        } else if (val < ptr->data) {
            insertHelper(ptr->leftPtr, val);
        } else if (val > ptr->data) {
            insertHelper(ptr->rightPtr, val);
        } else {
            std::cout << val << " dup\n";
        }
    }

    void inOrderHelper(const TreeNode<T>* ptr) const {
        if (ptr) {
            inOrderHelper(ptr->leftPtr.get());
            std::cout << ptr->data << ' ';
            inOrderHelper(ptr->rightPtr.get());
        }
    }

    void preOrderHelper(const TreeNode<T>* ptr) const {
        if (ptr) {
            std::cout << ptr->data << ' ';
            preOrderHelper(ptr->leftPtr.get());
            preOrderHelper(ptr->rightPtr.get());
        }
    }

    void postOrderHelper(const TreeNode<T>* ptr) const {
        if (ptr) {
            postOrderHelper(ptr->leftPtr.get());
            postOrderHelper(ptr->rightPtr.get());
            std::cout << ptr->data << ' ';
        }
    }
};

int main() {
    BST<int> tree;
    // Insert values from Fig 19.23: 27, 13, 42, 6, 17, 33, 48
    const int values[] = {27, 13, 42, 6, 17, 33, 48, 27};
    for (int v : values) {
        tree.insert(v);
    }

    std::cout << "Inorder: ";
    tree.inOrder();

    std::cout << "Preorder: ";
    tree.preOrder();

    std::cout << "Postorder: ";
    tree.postOrder();

    return 0;
}

#include <iostream>
#include <string>
#include <vector>

// Demonstrating concept synthesis: Stack (LIFO) vs Queue (FIFO)
template <typename T>
class SimpleStack {
    std::vector<T> elements;
public:
    void push(const T& val) { elements.push_back(val); }
    void pop() { if (!elements.empty()) elements.pop_back(); }
    T top() const { return elements.back(); }
    bool empty() const { return elements.empty(); }
};

template <typename T>
class SimpleQueue {
    std::vector<T> elements;
public:
    void enqueue(const T& val) { elements.push_back(val); }
    void dequeue() { if (!elements.empty()) elements.erase(elements.begin()); }
    T front() const { return elements.front(); }
    bool empty() const { return elements.empty(); }
};

int main() {
    SimpleStack<int> s;
    SimpleQueue<int> q;

    for (int v : {10, 20, 30}) {
        s.push(v);
        q.enqueue(v);
    }

    std::cout << "Stack LIFO: ";
    while (!s.empty()) {
        std::cout << s.top() << ' ';
        s.pop();
    }
    std::cout << '\n';

    std::cout << "Queue FIFO: ";
    while (!q.empty()) {
        std::cout << q.front() << ' ';
        q.dequeue();
    }
    std::cout << '\n';

    return 0;
}
